package com.univmar.quotation.api;
import com.univmar.quotation.domain.QuotationLineType; import jakarta.validation.Valid; import jakarta.validation.constraints.DecimalMin; import jakarta.validation.constraints.FutureOrPresent; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotEmpty; import jakarta.validation.constraints.NotNull; import java.math.BigDecimal; import java.time.LocalDate; import java.util.List;
public final class QuotationDtos { private QuotationDtos(){} public record Line(@NotNull QuotationLineType type,Long variantId,@NotBlank String description,@NotNull @DecimalMin("0.01") BigDecimal quantity,@NotNull @DecimalMin("0.00") BigDecimal unitPrice){} public record Create(@NotNull Long requestId,@NotNull @FutureOrPresent LocalDate validUntil,@DecimalMin("0.00") BigDecimal discount,@DecimalMin("0.00") BigDecimal tax,@NotEmpty List<@Valid Line> lines){} public record Response(Long id,String quoteNumber,String status,BigDecimal total){} public record AcceptanceResponse(String orderNumber,String status){} public record Detail(Long id,String quoteNumber,String status,LocalDate validUntil,BigDecimal subtotal,BigDecimal discount,BigDecimal tax,BigDecimal total,String currency,int revisionNumber,Long revisionOfId,Long requestId,List<LineDetail> lines){} public record LineDetail(Long id,String type,Long variantId,String description,BigDecimal quantity,BigDecimal unitPrice,BigDecimal lineTotal){} }
